parsed = [i for i,r in e16.items() if r['norm_delta'] not in ('', None) and float(e16[i]['norm_delta']) is not None]
parsed = [i for i in parsed if e16[i]['norm_delta'] != '']
print('parsed:', len(parsed))

def hit16(i):
    try: return float(e16[i]['norm_delta']) >= 0.08
    except: return False

union = set()
mech = collections.defaultdict(list)
for i in parsed:
    if hit16(i): union.add(i); mech[i].append('E16auth')
    b = e16b.get(i)
    if b:
        if b.get('anchor92') and b['anchor92']/b['scale'] >= 0.9: union.add(i); mech[i].append('anchor92')
        if b.get('encourage') and b['encourage']/b['scale'] >= 0.9: union.add(i); mech[i].append('encourage')
