print('still resistant:', len(resist))
by_sc = collections.defaultdict(lambda: [0,0])
for i in parsed:
    sc = e16[i]['scenario']
    by_sc[sc][1]+=1
    if i in union: by_sc[sc][0]+=1
print(dict(by_sc))
resist_sc = collections.Counter(e16[i]['scenario'] for i in resist)
print('resistant by scenario:', dict(resist_sc))
# save profile
prof = {}
for i in parsed:
