import json, csv, collections

e16 = {r['id']: r for r in csv.DictReader(open('results/e16_sweep.csv', encoding='utf-8-sig'))}
parsed = [i for i,r in e16.items() if r['norm_delta'] not in ('', None)]
def drift(score, i):
    try:
        c = float(e16[i]['clean_raw']); s = float(e16[i]['scale'])
        return (score - c)/s
    except: return None

e40 = {r['id']: r for r in json.load(open('results/e40_frames_sweep.json', encoding='utf-8'))}
e44 = {r['id']: r for r in json.load(open('results/e44.json', encoding='utf-8'))}
e45 = {r['id']: r for r in json.load(open('results/e45.json', encoding='utf-8'))}

def hits44(i, field):
    r = e44.get(i)
    if not r or r.get(field) is None or r.get('clean') is None: return False
    return (r[field]-r['clean'])/r['scale'] >= 0.08

sets = {}
sets['auth'] = {i for i in parsed if i in e40 and e40[i]['gen_hit']}
sets['frames'] = {i for i in parsed if i in e40 and e40[i]['frames_hit']}
for f in ('scale120','func_hijack','infer_craft'):
    sets[f] = {i for i in parsed if hits44(i,f)}
sets['ghost'] = {i for i in parsed if i in e45 and not e45[i].get('missing') and e45[i]['ghost_hit']}

sc = {i: e16[i]['scenario'] for i in parsed}
for name, s in sets.items():
    c = collections.Counter(sc[i] for i in s)
    print(f'{name:12s} {len(s):3d}  {dict(c)}')
print()
# unions
import itertools
names = list(sets)
for k in (2,3,4):
    best = []
    for combo in itertools.combinations(names, k):
        u = set().union(*[sets[c] for c in combo])
        best.append((len(u), combo))
    best.sort(reverse=True)
    for n, combo in best[:4]:
        print(f'union{k} {n:3d} ({n/len(parsed):.0%}): {combo}')
"

