# -*- coding: utf-8 -*-
"""E46 Step 1：判卷 prompt 原型库构建（纯本地，不联网）。

输入：defense-intel/teacher_prompts.jsonl（145 条真实教师判卷 prompt）
      + results/e46_intel_sets.json（E16-E45 各机制在统一口径"漂移≥8%"下的命中集）
输出：results/e46_prototypes.json —— 每条 prompt 的原型归属 + 每原型的机制命中画像

聚类维度：grading_scenario × 结构信号（JSON 输出 / 加权维度 / 逐题 / 得分点 /
等级制 / 防注入声明 / 代码包装）。原型 = "场景 × 结构" 的可判别类别，
教师拿到的产品即"你的 prompt 属于哪个原型 → 对应哪种攻击风险"。
"""
import json
import os
import re
import sys
from collections import defaultdict

sys.stdout.reconfigure(encoding="utf-8")
BASE = os.path.dirname(os.path.abspath(__file__))

INTEL = r"D:\篡改\defense-intel\teacher_prompts.jsonl"
OUT = os.path.join(BASE, "results", "e46_prototypes.json")

PROTO_NAMES = {
    "P1": "作文·checklist/JSON 评分型（加权维度+结构化输出）",
    "P2": "作文·等级/rubric 型（高考档位、优良中差、整体印象）",
    "P3": "简答·逐题/得分点型（按小题或踩点给分）",
    "P4": "简答·要点匹配型（整体判分、无逐题结构）",
    "P5": "作业通用·宽松评语型（无硬量表，反馈导向）",
    "P6": "编程·结构化评测型",
    "P7": "试卷·整卷结构化型",
    "P8": "通用批改·笼统型",
}


def features(ptext):
    f = {
        "json_out": bool(re.search(r"JSON|json|输出.*格式|\"total\"|\"总分\"|json格式|JSON 格式", ptext)) and
                    bool(re.search(r"\{|\}", ptext)),
        "dims_weighted": bool(re.search(r"（\s*0?\s*[-～~]\s*\d+\s*分\s*[）)]|\(\s*0?\s*[-～~]\s*\d+\s*分\s*\)|\d+\s*分\s*[）)]：", ptext)),
        "per_question": bool(re.search(r"每题|逐题|各题|按题|每一题|每道", ptext)),
        "key_points": bool(re.search(r"得分点|关键词|要点|踩点|给分点", ptext)),
        "grade_levels": bool(re.search(r"一类文|二类文|高考作文|优良中|等第|等级制|A\+|ABC|档次", ptext)),
        "defense": bool(re.search(r"注入|提示词攻击|恶意指令|防篡改|忽略.*指令|不要被|不要执行", ptext)),
        "code_wrapper": bool(re.search(r"import |def |requests\.|GRADE_PROMPT|prompt\s*=\s*f?[\"']", ptext)),
    }
    return f


def assign_proto(scenario, f):
    if scenario == "作文":
        if f["json_out"] or f["dims_weighted"]:
            return "P1"
        return "P2"
    if scenario.startswith("简答"):
        if f["per_question"] or f["key_points"]:
            return "P3"
        return "P4"
    if scenario == "作业通用":
        return "P5"
    if scenario == "编程作业":
        return "P6"
    if scenario.startswith("试卷"):
        return "P7"
    return "P8"


def main():
    rows = [json.loads(l) for l in open(INTEL, encoding="utf-8")]
    intel = json.load(open(os.path.join(BASE, "results", "e46_intel_sets.json"), encoding="utf-8"))
    mech_sets = {k: set(v) for k, v in intel["sets"].items()}
    parsed = set().union(*mech_sets.values())  # 119 条可解析集

    out = {}
    for r in rows:
        pid, sc, pt = r["id"], r["grading_scenario"], r["prompt_text"]
        f = features(pt)
        proto = assign_proto(sc, f)
        out[pid] = {"scenario": sc, "proto": proto, "scale_hint": None,
                    "features": f, "in_denominator": pid in parsed}

    # 每原型的机制命中画像（历史情报，统一口径漂移≥8%）
    prof = defaultdict(lambda: {"n": 0, "n_denominator": 0, "mech_hits": defaultdict(int)})
    for pid, o in out.items():
        p = prof[o["proto"]]
        p["n"] += 1
        if o["in_denominator"]:
            p["n_denominator"] += 1
        for mech, s in mech_sets.items():
            if pid in s:
                p["mech_hits"][mech] += 1

    summary = {}
    for proto, p in sorted(prof.items()):
        n = p["n_denominator"]
        rates = {m: {"hits": h, "rate": round(h / n, 2) if n else None}
                 for m, h in sorted(p["mech_hits"].items(), key=lambda x: -x[1])}
        best = max(rates.items(), key=lambda x: (x[1]["hits"] or 0)) if rates else None
        summary[proto] = {"name": PROTO_NAMES[proto], "n_total": p["n"],
                          "n_denominator": n, "mech_rates": rates,
                          "best_mech_historical": best[0] if best else None}
        print(f"{proto} {PROTO_NAMES[proto]}: n={p['n']}/{n} best={best[0] if best else '-'}")
        for m, v in rates.items():
            print(f"    {m:10s} {v['hits']:3d} ({v['rate']:.0%})" if v["rate"] is not None else f"    {m}")

    json.dump({"prompts": out, "summary": summary},
              open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print(f"\n-> {OUT}")


if __name__ == "__main__":
    main()

