    "P3": "简答·逐题/得分点型（按小题或踩点给分）",
    "P4": "简答·要点匹配型（整体判分、无逐题结构）",
    "P5": "作业通用·宽松评语型（无硬量表，反馈导向）",
    "P6": "编程·结构化评测型",
    "P7": "试卷·整卷结构化型",
    "P8": "通用批改·笼统型",
}


def features(ptext):
    f = {
        "json_out": bool(re.search(r"JSON|json|输出.*格式|\"total\"|\"总分\"|json格式|JSON 格式", ptext)) and
                    bool(re.search(r"\{|\}", ptext)),
        "dims_weighted": bool(re.search(r"（\s*0?\s*[-～~]\s*\d+\s*分\s*[）)]|\(\s*0?\s*[-～~]\s*\d+\s*分\s*\)|\d+\s*分\s*[）)]：", ptext)),
        "per_question": bool(re.search(r"每题|逐题|各题|按题|每一题|每道", ptext)),
        "key_points": bool(re.search(r"得分点|关键词|要点|踩点|给分点", ptext)),
        "grade_levels": bool(re.search(r"一类文|二类文|高考作文|优良中|等第|等级制|A\+|ABC|档次", ptext)),
        "defense": bool(re.search(r"注入|提示词攻击|恶意指令|防篡改|忽略.*指令|不要被|不要执行", ptext)),
        "code_wrapper": bool(re.search(r"import |def |requests\.|GRADE_PROMPT|prompt\s*=\s*f?[\"']", ptext)),
    }
    return f


def assign_proto(scenario, f):
    if scenario == "作文":
        if f["json_out"] or f["dims_weighted"]:
