    print(f"E16 可解析分母: {len(parsed)} 条")

    out = {}
    for r in rows:
        pid, sc, pt = r["id"], r["grading_scenario"], r["prompt_text"]
        f = features(pt)
        proto = assign_proto(sc, f)
        out[pid] = {"scenario": sc, "proto": proto, "scale_hint": None,
                    "features": f, "in_denominator": pid in parsed}

